function canonicalTeamName(name,code){const key=normalizeTeamName(name),aliases={'esp.1':{deportivoalaves:'alaves',deportivoacoruna:'deportivo',espanyolbarcelona:'espanyol',levanteud:'levante',villareal:'villarreal'},'ger.1':{bayernmunchen:'bayernmunich'}};return aliases[code]?.[key]||key}
