function normalizeEvent(e,code,name,fetchedAt){const c=e.competitions?.[0]||{},home=c.competitors?.find(x=>x.homeAway==='home')||{},away=c.competitors?.find(x=>x.homeAway==='away')||{},status=e.status||c.status||{},statusType=status.type||{},statusName=statusType.name||'STATUS_UNKNOWN',score=/SCHEDULED|STATUS_PRE/i.test(statusName)?null:scoreOf(e),record=x=>x.records?.find(r=>r.type==='total')?.summary||x.records?.[0]?.summary||'';return {id:String(e.id),competitionId:code,competition:name,home:home.team?.displayName||home.team?.shortDisplayName||'Home team',away:away.team?.displayName||away.team?.shortDisplayName||'Away team',homeAbbr:home.team?.abbreviation,awayAbbr:away.team?.abbreviation,homeLogo:teamLogoUrl(home.team),awayLogo:teamLogoUrl(away.team),homeRecord:record(home),awayRecord:record(away),kickoffUtc:e.date,status:statusName,statusText:statusType.shortDetail||statusType.detail||'',displayClock:status.displayClock||'',period:Number(status.period)||null,score,fetchedAt}}
function allMatches(){const dateKey=localDateKey(selectedDate());return state.eventsDate===dateKey?eventsForMyanmarDate(state.events,dateKey):[]}
function statusKey(m){if(/HALFTIME/i.test(m.status)||/half[ -]?time/i.test(m.statusText||''))return 'halftime';if(/STATUS_(FINAL|FULL_TIME)/i.test(m.status))return 'finished';if(/STATUS_(POSTPONED|CANCELED|CANCELLED)/i.test(m.status))return 'cancelled';if(/STATUS_(IN_PROGRESS|FIRST_HALF|SECOND_HALF|EXTRA_TIME|EXTRA_TIME_HALFTIME)/i.test(m.status))return 'live';return new Date(m.kickoffUtc)>new Date()?'upcoming':'unknown'}
